using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // In .NET 9, ZipArchiveEntry now respects the UTF-8 flag and
        // encodes names as UTF-8 by default. The legacy Java consumer
        // expects Shift-JIS, so we must specify the encoding explicitly.
        var shiftJis = CodePagesEncodingProvider.Instance.GetEncoding(932)
            ?? Encoding.UTF8;
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// In .NET 9, [FromKeyedServices("cache")] no longer falls back
// to a non-keyed registration. Register as a keyed service.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

